"""Decoder for the internal ``trk`` telemetry record format.

Each frame has a one-byte type, a little-endian uint16 payload length,
its payload, and a little-endian CRC32 of the header and payload. The CRC
uses the device's initial seed, 0x9C2F41B7.

Sample payloads contain big-endian minute timestamps (epoch 2000-01-02),
a big-endian uint24 value in thousandths, and a flag byte. Batch payloads
contain a big-endian uint16 count, uint16 values in hundredths, and flags.
"""

from datetime import datetime, timedelta, timezone
import zlib


_CRC_SEED = 0x9C2F41B7
_EPOCH = datetime(2000, 1, 2, tzinfo=timezone.utc)
_FLAG_NAMES = ("low_battery", "recal", "stale")


def decode_records(data: bytes) -> list[dict]:
    """Decode complete frames, rejecting truncated or corrupt input."""
    records = []
    offset = 0
    while offset < len(data):
        if len(data) - offset < 3:
            raise ValueError(f"truncated record header at offset {offset}")
        kind = data[offset]
        size = int.from_bytes(data[offset + 1:offset + 3], "little")
        payload_start = offset + 3
        payload_end = payload_start + size
        frame_end = payload_end + 4
        if frame_end > len(data):
            raise ValueError(f"truncated record at offset {offset}")

        checksum = int.from_bytes(data[payload_end:frame_end], "little")
        if zlib.crc32(data[offset:payload_end], _CRC_SEED) != checksum:
            raise ValueError(f"checksum mismatch at offset {offset}")

        payload = data[payload_start:payload_end]
        if kind == 2:
            if size != 8:
                raise ValueError(f"invalid sample length at offset {offset}")
            minutes = int.from_bytes(payload[:4], "big")
            timestamp = _EPOCH + timedelta(minutes=minutes)
            record = {
                "type": "sample",
                "ts": timestamp.strftime("%Y-%m-%dT%H:%M:%SZ"),
                "value": int.from_bytes(payload[4:7], "big") / 1000,
            }
        elif kind == 7:
            if size < 3:
                raise ValueError(f"invalid batch length at offset {offset}")
            count = int.from_bytes(payload[:2], "big")
            if size != 3 + 2 * count:
                raise ValueError(f"invalid batch length at offset {offset}")
            record = {
                "type": "batch",
                "values": [
                    int.from_bytes(payload[i:i + 2], "big") / 100
                    for i in range(2, 2 + 2 * count, 2)
                ],
            }
        else:
            raise ValueError(f"unknown record type {kind} at offset {offset}")

        record["flags"] = [
            name for bit, name in enumerate(_FLAG_NAMES)
            if payload[-1] & (1 << bit)
        ]
        records.append(record)
        offset = frame_end
    return records
PY
